/**
 * NET Study PDF.js bootstrap (PDF.js 3.11.174)
 * Keeps index.html pointed at a same-origin ./pdf.min.js file while using
 * multiple package-CDN fallbacks for the vendor build on first use.
 * Successful remote responses are also eligible for caching by the PWA service worker.
 */
(function(g){
  'use strict';
  if(g.pdfjsLib){g.__NET_PDFJS_READY__=Promise.resolve(g.pdfjsLib);return;}
  if(g.__NET_PDFJS_READY__)return;
  var urls=[
    'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js',
    'https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js'
  ];
  g.__NET_PDFJS_READY__=new Promise(function(resolve,reject){
    var i=0,lastErr=null;
    function next(){
      if(g.pdfjsLib){resolve(g.pdfjsLib);return;}
      if(i>=urls.length){reject(lastErr||new Error('PDF.js could not be loaded from any fallback source.'));return;}
      var s=document.createElement('script'),u=urls[i++];
      s.src=u;s.async=true;s.crossOrigin='anonymous';
      s.onload=function(){
        try{s.remove()}catch(e){}
        if(g.pdfjsLib){try{g.pdfjsLib.GlobalWorkerOptions.workerSrc='./pdf.worker.min.js'}catch(e){}resolve(g.pdfjsLib)}
        else{lastErr=new Error('PDF.js loaded but did not initialize from '+u);next();}
      };
      s.onerror=function(){try{s.remove()}catch(e){}lastErr=new Error('PDF.js source failed: '+u);next();};
      document.head.appendChild(s);
    }
    next();
  });
})(window);
